// 무료 한도 안에서만: 하루 처리할 상품 수/키워드 고정
const MAX = 3; // config.json 의 daily.maxProductsPerDay 와 동일하게 유지
const keywords = ['홈오피스 생산성', '재택 가젯', 'AI 자동화 소품'];
const kw = keywords[(new Date().getDate()) % keywords.length];
return [{ json: { keyword: kw, max: MAX } }];

// 무료 한도 보호: 결과를 max 개로 잘라 사양/키워드만 추출 (이미지 URL 게시 금지)
const max = $('일일 한도 설정').first().json.max;
const data = items[0].json.data || items[0].json.results || [];
return data.slice(0, max).map((r) => ({
  json: {
    title: r.title || r.metadata?.title || '',
    url: r.url || '',
    summary: (r.markdown || r.description || '').slice(0, 1500)
  }
}));

