// 카피 정리 + 쿠팡 링크 자리 + 대가성 문구 확인
const disclosure = '이 포스팅은 쿠팡파트너스 활동의 일환으로, 이에 따른 일정액의 수수료를 제공받습니다.';
const src = $('한도 적용 + 사양만 추출').all();
return items.map((it, i) => {
  let copy = it.json?.candidates?.[0]?.content?.parts?.[0]?.text || '';
  if (!copy.includes('쿠팡파트너스 활동')) copy += '\n\n' + disclosure;
  return { json: {
    title: src[i]?.json.title || '',
    refUrl: src[i]?.json.url || '',
    coupangLink: '{쿠팡링크 — 쿠팡 검색 후 파트너스 딥링크로 교체}',
    detailPageCopy: copy,
    status: 'DRAFT — 게시 전 사람 검수(과장/대가성/정품링크) 필요'
  } };
});
